css:
.call{display:flex;align-items:center;gap:22px;background:rgba(0,0,0,.25);padding:18px 36px;border-radius:999px;font-weight:900;font-size:52px}.rec{width:28px;height:28px;border-radius:50%;background:#ff2d2d;animation:pulse .9s ease-in-out infinite!important;animation-play-state:paused!important}.tr{width:1060px;display:flex;flex-direction:column;gap:18px}.ln{font-size:44px;font-weight:600;line-height:1.35;background:#15151f;border-radius:24px;padding:16px 28px;animation:slide .45s ease-out;animation-delay:calc(var(--t) + var(--d,0s))}.ln b{color:#8f8fa3;font-weight:600}.ln mark{background:none;color:#111;position:relative;padding:0 6px;background-image:linear-gradient(#ffd23f,#ffd23f);background-repeat:no-repeat;background-size:100% 100%;animation:hl .4s ease-out;animation-delay:calc(var(--t) + var(--d,0s) + .55s);border-radius:6px}@keyframes hl{from{background-size:0% 100%;color:#fff}to{background-size:100% 100%;color:#111}}.live{position:absolute;top:34px;right:44px;font-size:34px;font-weight:900;display:flex;gap:12px;align-items:center}.chips{display:flex;gap:20px;justify-content:center;width:1240px}.cp{background:#fff;color:#111;border-radius:30px;padding:20px 26px;text-align:center}.cp small{display:block;font-size:32px;color:#666;font-weight:600}.cp b{font-size:54px;font-weight:900}.q{background:#fff;color:#111;border-radius:36px;padding:34px 50px;width:960px;box-shadow:0 30px 80px rgba(0,0,0,.35)}.q h3{margin:0;font-size:52px;font-weight:900;display:flex;justify-content:space-between;align-items:center}.q h3 span{font-size:30px;background:#2ee59d;color:#063;padding:6px 18px;border-radius:999px}.qr{display:flex;justify-content:space-between;font-size:40px;font-weight:600;padding:12px 0;border-bottom:2px dashed #e6e6e6;animation:slide .4s ease-out;animation-delay:calc(var(--t) + var(--d,0s))}.qr span:last-child{direction:ltr}.qt{font-weight:900;font-size:50px;border:0}.gold{background:radial-gradient(circle at 50% 40%,#ffe9a3,#e8a917 55%,#8a5a00)}.gbig{color:#2a1a00!important;font-size:170px!important;text-align:center;letter-spacing:-3px}.send{background:#111;color:#fff;font-weight:900;font-size:50px;padding:22px 50px;border-radius:26px}.rowc{display:flex;justify-content:space-between;font-size:46px;font-weight:600;padding:14px 0;border-top:2px solid #eadfcd;animation:slide .45s ease-out;animation-delay:calc(var(--t) + var(--d,0s))}.rowc b{color:#e8590c;font-weight:900;direction:rtl}.ok{align-self:center;background:#2ee59d;color:#063;font-weight:900;font-size:46px;padding:14px 40px;border-radius:999px;animation:slide .4s ease-out;animation-delay:calc(var(--t) + var(--d,0s))}.who{font-size:30px;font-weight:700;opacity:.7;display:block;margin-bottom:4px}.seen{align-self:center;font-size:54px;font-weight:900;color:#ff6b6b;margin-top:14px;animation:slide .4s ease-out;animation-delay:calc(var(--t) + var(--d,0s))}.meter{width:900px;height:70px;border-radius:999px;background:#fff3;position:relative;overflow:hidden}.meter i{position:absolute;inset:0 auto 0 0;background:#2ee59d;border-radius:999px;animation:drain 1.6s ease-in-out;animation-delay:calc(var(--t) + .5s)}@keyframes drain{from{width:85%;background:#2ee59d}to{width:30%;background:#ff3b3b}}.thr{position:absolute;top:-8px;bottom:-8px;left:42%;width:8px;background:#111;border-radius:4px}.red{background:#ff3b3b;color:#fff;font-weight:900;font-size:52px;padding:14px 40px;border-radius:999px;transform:rotate(-3deg)}.btn{background:#1638ff;color:#fff;font-weight:900;font-size:64px;padding:28px 70px;border-radius:30px;box-shadow:0 20px 50px rgba(22,56,255,.45)}.stamp{font-weight:900;font-size:120px;color:#2ee59d;border:10px solid #2ee59d;border-radius:30px;padding:6px 50px;transform:rotate(-6deg)}
.mail{background:#fff;color:#111;border-radius:40px;padding:40px 46px;width:900px;box-shadow:0 30px 80px rgba(0,0,0,.35)}
.mail .from{font-size:34px;color:#666;font-weight:600}.mail h3{margin:8px 0 18px;font-size:62px;font-weight:900}
.att{display:flex;align-items:center;gap:20px;background:#f3f1ec;border-radius:24px;padding:20px 26px;font-size:44px;font-weight:900}
.att i{font-style:normal;background:#ff5a1f;color:#fff;border-radius:14px;padding:6px 16px;font-size:34px}
.bank{width:960px;display:flex;flex-direction:column;gap:22px}
.bl{display:flex;justify-content:space-between;align-items:center;background:#15151f;border-radius:26px;padding:24px 30px;font-size:44px;font-weight:600;animation:slide .45s ease-out;animation-delay:calc(var(--t) + var(--d,0s))}
.bl b{font-weight:900;font-size:50px}.bl small{display:block;font-size:30px;color:#9a9ab0}
.bl.hot{background:#3a0d12;border:5px solid #ff3b3b}
.bl .tk{color:#2ee59d;font-weight:900;font-size:46px}
.n{direction:ltr;unicode-bidi:isolate;display:inline-block}
.hd{font-weight:900;font-size:84px;line-height:1.05;text-align:center}
.huge{font-weight:900;font-size:200px;line-height:.9;color:#fff;letter-spacing:-4px}
.ret{font-weight:900;font-size:66px;color:#2ee59d}
.sc{gap:44px}.sc>*:not(.bgfx):not(.live){zoom:1.12}.bank{width:860px}.mail{width:840px}.q{width:860px}.hd{font-size:92px}
